export const BASELINE_SQL = "-- BirthNote schema, FROZEN as the baseline migration (0001_baseline).\n--\n-- Do not edit this file to change the schema. It is compiled into\n-- src/server/migrations/0001_baseline.sql.ts and applied once per database;\n-- every change since lives in a numbered file under src/server/migrations/.\n-- It remains valid as a phpMyAdmin paste for a brand-new database, and the\n-- app applies the later migrations on its first start either way.\n\n-- NOTE: the per-note columns below (note_date, display_date, gift_for, and the\n-- note_* fields) moved to order_items in Phase 3. They are still created here\n-- because that is what lets one backfill path serve both a pre-bulk database\n-- and a brand-new one: migration 0004_order_items copies them into order_items\n-- and then drops them. On a fresh install they exist for the length of a\n-- single migration.\nCREATE TABLE IF NOT EXISTS orders (\n  id                BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,\n  reference         VARCHAR(24)     NOT NULL,\n  note_date         DATE            NOT NULL,\n  display_date      VARCHAR(10)     NOT NULL,\n  customer_name     VARCHAR(160)    NOT NULL,\n  customer_email    VARCHAR(190)    NOT NULL,\n  -- Added by 0005_whatsapp on databases that predate Phase 5.\n  whatsapp          VARCHAR(24)          NULL,\n  whatsapp_opt_in   TINYINT(1)      NOT NULL DEFAULT 0,\n  gift_for          VARCHAR(160)         NULL,\n  message           TEXT                 NULL,\n  status            ENUM('pending','checking','confirmed','unavailable','paid','shipped')\n                                    NOT NULL DEFAULT 'pending',\n  price_paise       INT UNSIGNED    NOT NULL DEFAULT 249900,\n  currency          CHAR(3)         NOT NULL DEFAULT 'INR',\n  note_denomination VARCHAR(120)         NULL,\n  note_condition    VARCHAR(60)          NULL,\n  note_serial       VARCHAR(60)          NULL,\n  note_country      VARCHAR(80)          NULL,\n  admin_notes       TEXT                 NULL,\n  stripe_session_id VARCHAR(255)         NULL,\n  stripe_payment_id VARCHAR(255)         NULL,\n  paid_at           DATETIME             NULL,\n  tracking_number   VARCHAR(120)         NULL,\n  created_at        DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at        DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP\n                                             ON UPDATE CURRENT_TIMESTAMP,\n  PRIMARY KEY (id),\n  UNIQUE KEY uq_orders_reference (reference),\n  KEY idx_orders_status_created (status, created_at),\n  KEY idx_orders_email (customer_email),\n  KEY idx_orders_session (stripe_session_id)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\n\n-- Append-only audit trail shown as the timeline on the tracking page.\nCREATE TABLE IF NOT EXISTS order_events (\n  id          BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,\n  order_id    BIGINT UNSIGNED NOT NULL,\n  status      VARCHAR(32)     NOT NULL,\n  note        VARCHAR(500)         NULL,\n  actor       VARCHAR(40)     NOT NULL DEFAULT 'system',\n  created_at  DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id),\n  KEY idx_events_order (order_id, created_at),\n  CONSTRAINT fk_events_order FOREIGN KEY (order_id)\n    REFERENCES orders (id) ON DELETE CASCADE\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\n\n-- Guards the public request form against a single IP flooding the queue.\nCREATE TABLE IF NOT EXISTS rate_limits (\n  bucket      VARCHAR(120)    NOT NULL,\n  hits        INT UNSIGNED    NOT NULL DEFAULT 1,\n  window_start DATETIME       NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (bucket)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\n\n-- ---------------------------------------------------------------------------\n-- Phase 1: customer accounts\n-- ---------------------------------------------------------------------------\n\n-- The mobile number is the account identifier: people sign in with a one-time\n-- code sent by SMS, so `phone` is the unique key and `email` is an optional\n-- extra we use for receipts.\n--\n-- There is no `password_hash` column: a customer account has no password at\n-- all, only a number that can be sent a code. Admins are a separate table and\n-- keep theirs.\n--\n-- Two columns are nullable that the old email-and-password design would not\n-- have allowed, and each for a reason:\n--   * `email` — optional now, so it must accept NULL. MySQL permits any number\n--     of NULLs in a UNIQUE key, which is exactly the behaviour wanted: at most\n--     one account per address, unlimited accounts with no address at all.\n--   * `phone` — NOT NULL for anyone created from here on, but accounts that\n--     predate this change have no number on file and must not be deleted. The\n--     column stays nullable so they survive; they add a number the first time\n--     they sign in.\nCREATE TABLE IF NOT EXISTS users (\n  id              BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,\n  name            VARCHAR(160)    NOT NULL DEFAULT '',\n  email           VARCHAR(190)         NULL,\n  phone           VARCHAR(24)          NULL,\n  whatsapp        VARCHAR(24)          NULL,\n  phone_verified  TINYINT(1)      NOT NULL DEFAULT 0,\n  email_verified  TINYINT(1)      NOT NULL DEFAULT 0,\n  created_at      DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at      DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP\n                                           ON UPDATE CURRENT_TIMESTAMP,\n  PRIMARY KEY (id),\n  UNIQUE KEY uq_users_email (email),\n  UNIQUE KEY uq_users_phone (phone)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\n\n-- One-time sign-in codes.\n--\n-- A code belongs to an identifier — a canonical mobile number or an email\n-- address — and to the channel it went out on. Both are in the key: a code\n-- texted to a number must not be spendable against an address, or offering two\n-- ways in would become one way in for someone holding neither.\n--\n-- Only the SHA-256 of each code is stored, for the same reason session tokens\n-- are hashed: a database leak must not hand anyone a working credential. A\n-- six-digit code is small enough to brute-force in seconds if guessing were\n-- free, so `attempts` caps it at five tries and the row is spent either way.\n--\n-- Rows are kept after use rather than deleted, so `consumed_at` can prove a\n-- code was already redeemed and refuse to honour it twice.\nCREATE TABLE IF NOT EXISTS auth_otps (\n  id           BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,\n  -- Wide enough for an email address; `users.email` is the same 190.\n  identifier   VARCHAR(190)    NOT NULL,\n  channel      VARCHAR(8)      NOT NULL DEFAULT 'sms',\n  code_hash    CHAR(64)        NOT NULL,\n  purpose      VARCHAR(24)     NOT NULL DEFAULT 'auth',\n  attempts     TINYINT UNSIGNED NOT NULL DEFAULT 0,\n  consumed_at  DATETIME             NULL,\n  expires_at   DATETIME        NOT NULL,\n  created_at   DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id),\n  KEY idx_auth_otps_lookup (identifier, channel, purpose, expires_at),\n  KEY idx_auth_otps_expiry (expires_at)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\n\n-- Only the SHA-256 of each session token is stored, so a database leak does\n-- not hand an attacker a set of live sessions.\nCREATE TABLE IF NOT EXISTS user_sessions (\n  id           BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,\n  user_id      BIGINT UNSIGNED NOT NULL,\n  token_hash   CHAR(64)        NOT NULL,\n  user_agent   VARCHAR(255)         NULL,\n  created_at   DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  expires_at   DATETIME        NOT NULL,\n  PRIMARY KEY (id),\n  UNIQUE KEY uq_sessions_token (token_hash),\n  KEY idx_sessions_user (user_id, expires_at),\n  KEY idx_sessions_expiry (expires_at),\n  CONSTRAINT fk_sessions_user FOREIGN KEY (user_id)\n    REFERENCES users (id) ON DELETE CASCADE\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\n\n-- There is no `password_resets` table: customers have no password to reset.\n-- Losing access means asking for another code, which expires in ten minutes.\n-- Admins keep theirs, as `admin_password_resets` below.\n\n-- ---------------------------------------------------------------------------\n-- Phase 2: admin users and roles\n-- ---------------------------------------------------------------------------\n\n-- Replaces the single shared ADMIN_PASSWORD. Roles are deliberately just two:\n--   owner — everything, including managing other admins\n--   staff — the order queue only\n-- More levels can be added when a real need appears; inventing them now would\n-- only be guesswork encoded in an ENUM.\nCREATE TABLE IF NOT EXISTS admin_users (\n  id             BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,\n  name           VARCHAR(160)    NOT NULL,\n  email          VARCHAR(190)    NOT NULL,\n  password_hash  VARCHAR(255)    NOT NULL,\n  role           ENUM('owner','staff') NOT NULL DEFAULT 'staff',\n  is_active      TINYINT(1)      NOT NULL DEFAULT 1,\n  last_login_at  DATETIME             NULL,\n  created_at     DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at     DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP\n                                          ON UPDATE CURRENT_TIMESTAMP,\n  PRIMARY KEY (id),\n  UNIQUE KEY uq_admin_email (email)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\n\nCREATE TABLE IF NOT EXISTS admin_sessions (\n  id             BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,\n  admin_user_id  BIGINT UNSIGNED NOT NULL,\n  token_hash     CHAR(64)        NOT NULL,\n  user_agent     VARCHAR(255)         NULL,\n  created_at     DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  expires_at     DATETIME        NOT NULL,\n  PRIMARY KEY (id),\n  UNIQUE KEY uq_admin_sessions_token (token_hash),\n  KEY idx_admin_sessions_user (admin_user_id, expires_at),\n  CONSTRAINT fk_admin_sessions_user FOREIGN KEY (admin_user_id)\n    REFERENCES admin_users (id) ON DELETE CASCADE\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\n\nCREATE TABLE IF NOT EXISTS admin_password_resets (\n  id             BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,\n  admin_user_id  BIGINT UNSIGNED NOT NULL,\n  token_hash     CHAR(64)        NOT NULL,\n  expires_at     DATETIME        NOT NULL,\n  used_at        DATETIME             NULL,\n  created_at     DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id),\n  UNIQUE KEY uq_admin_resets_token (token_hash),\n  KEY idx_admin_resets_user (admin_user_id),\n  CONSTRAINT fk_admin_resets_user FOREIGN KEY (admin_user_id)\n    REFERENCES admin_users (id) ON DELETE CASCADE\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\n\n-- ---------------------------------------------------------------------------\n-- Phase 3: bulk orders\n-- ---------------------------------------------------------------------------\n\n-- One row per banknote. An order is now the parent — one customer, one\n-- payment, one parcel — and every order has at least one item, including the\n-- single-note orders that predate this table (0004_order_items backfills them).\n--\n-- Availability is per item, not per order: finding four dates out of five\n-- should not cost the customer the other four. The order's price_paise is the\n-- sum of the available items' prices, recomputed whenever an item changes.\nCREATE TABLE IF NOT EXISTS order_items (\n  id                BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,\n  order_id          BIGINT UNSIGNED NOT NULL,\n  -- Preserves the order the customer typed the dates in.\n  position          SMALLINT UNSIGNED NOT NULL DEFAULT 1,\n  note_date         DATE            NOT NULL,\n  display_date      VARCHAR(10)     NOT NULL,\n  requested_denomination SMALLINT UNSIGNED NULL,\n  gift_relationship VARCHAR(40)          NULL,\n  gift_for          VARCHAR(160)         NULL,\n  availability      ENUM('pending','available','unavailable')\n                                    NOT NULL DEFAULT 'pending',\n  -- Set by the admin when they confirm this note. Null until then.\n  price_paise       INT UNSIGNED         NULL,\n  note_denomination VARCHAR(120)         NULL,\n  note_condition    VARCHAR(60)          NULL,\n  note_serial       VARCHAR(60)          NULL,\n  note_country      VARCHAR(80)          NULL,\n  created_at        DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at        DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP\n                                             ON UPDATE CURRENT_TIMESTAMP,\n  PRIMARY KEY (id),\n  KEY idx_items_order (order_id, position),\n  KEY idx_items_date (note_date),\n  CONSTRAINT fk_items_order FOREIGN KEY (order_id)\n    REFERENCES orders (id) ON DELETE CASCADE\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\n\n-- ---------------------------------------------------------------------------\n-- Phase 4: static pages, blog and SEO\n-- ---------------------------------------------------------------------------\n\n-- Editable marketing pages, reachable at /<slug>.\n--\n-- `slug` is unique and validated against a reserved list in the application:\n-- Next.js matches its own static routes before /[slug], so a page slugged\n-- \"login\" would save fine and then never be reachable.\nCREATE TABLE IF NOT EXISTS pages (\n  id               BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,\n  slug             VARCHAR(160)    NOT NULL,\n  title            VARCHAR(200)    NOT NULL,\n  body_markdown    MEDIUMTEXT      NOT NULL,\n  -- Falls back to `title` when blank, so a page is never published without\n  -- something sensible in the <title>.\n  meta_title       VARCHAR(200)         NULL,\n  meta_description VARCHAR(320)         NULL,\n  status           ENUM('draft','published') NOT NULL DEFAULT 'draft',\n  updated_by       VARCHAR(190)         NULL,\n  created_at       DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at       DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP\n                                            ON UPDATE CURRENT_TIMESTAMP,\n  PRIMARY KEY (id),\n  UNIQUE KEY uq_pages_slug (slug),\n  KEY idx_pages_status (status)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\n\nCREATE TABLE IF NOT EXISTS blog_categories (\n  id               BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,\n  slug             VARCHAR(160)    NOT NULL,\n  name             VARCHAR(160)    NOT NULL,\n  description      VARCHAR(500)         NULL,\n  meta_title       VARCHAR(200)         NULL,\n  meta_description VARCHAR(320)         NULL,\n  created_at       DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at       DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP\n                                            ON UPDATE CURRENT_TIMESTAMP,\n  PRIMARY KEY (id),\n  UNIQUE KEY uq_categories_slug (slug)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\n\nCREATE TABLE IF NOT EXISTS blog_posts (\n  id               BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,\n  slug             VARCHAR(160)    NOT NULL,\n  title            VARCHAR(200)    NOT NULL,\n  excerpt          VARCHAR(500)         NULL,\n  body_markdown    MEDIUMTEXT      NOT NULL,\n  -- Deleting a category must not delete the writing filed under it.\n  category_id      BIGINT UNSIGNED      NULL,\n  cover_image_url  VARCHAR(500)         NULL,\n  meta_title       VARCHAR(200)         NULL,\n  meta_description VARCHAR(320)         NULL,\n  status           ENUM('draft','published') NOT NULL DEFAULT 'draft',\n  -- Set the first time a post is published, then left alone, so re-editing\n  -- an old post does not shuffle it back to the top of the blog.\n  published_at     DATETIME             NULL,\n  author_name      VARCHAR(160)         NULL,\n  updated_by       VARCHAR(190)         NULL,\n  created_at       DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at       DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP\n                                            ON UPDATE CURRENT_TIMESTAMP,\n  PRIMARY KEY (id),\n  UNIQUE KEY uq_posts_slug (slug),\n  KEY idx_posts_published (status, published_at),\n  KEY idx_posts_category (category_id, status),\n  CONSTRAINT fk_posts_category FOREIGN KEY (category_id)\n    REFERENCES blog_categories (id) ON DELETE SET NULL\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\n";
